//! Value system for Omnia with infinite precision mathematics\n\nuse std::fmt;\nuse std::collections::HashMap;\nuse crate::error::{OmniaError, Result};\n\n/// Represents a value in Omnia with support for infinite precision\n#[derive(Debug, Clone)]\npub enum Value {\n    /// Infinite precision integer (represented as String)\n    Integer(String),\n    /// Infinite precision float (represented as String)\n    Float(String),\n    /// Boolean value\n    Bool(bool),\n    /// String value (pure ASCII)\n    String(String),\n    /// Array of values\n    Array(Vec<Value>),\n    /// Object/Map with key-value pairs\n    Object(HashMap<String, Value>),\n    /// Null value\n    Null,\n}\n\nimpl fmt::Display for Value {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        match self {\n            Value::Integer(n) => write!(f, \"{}\", n),\n            Value::Float(n) => write!(f, \"{}\", n),\n            Value::Bool(b) => write!(f, \"{}\", b),\n            Value::String(s) => write!(f, \"{}\", s),\n            Value::Array(arr) => {\n                write!(f, \"[\").ok();\n                for (i, v) in arr.iter().enumerate() {\n                    if i > 0 {\n                        write!(f, \", \").ok();\n                    }\n                    write!(f, \"{}\", v).ok();\n                }\n                write!(f, \"]\")\n            }\n            Value::Object(map) => {\n                write!(f, \"{{\").ok();\n                for (i, (k, v)) in map.iter().enumerate() {\n                    if i > 0 {\n                        write!(f, \", \").ok();\n                    }\n                    write!(f, \"\\\"{}\\\": {}\", k, v).ok();\n                }\n                write!(f, \"}}\")\n            }\n            Value::Null => write!(f, \"null\"),\n        }\n    }\n}\n\nimpl Value {\n    /// Check if value is truthy\n    pub fn is_truthy(&self) -> bool {\n        match self {\n            Value::Bool(b) => *b,\n            Value::Null => false,\n            Value::Integer(n) => n != \"0\" && !n.is_empty(),\n            Value::Float(n) => n != \"0.0\" && n != \"0\" && !n.is_empty(),\n            Value::String(s) => !s.is_empty(),\n            Value::Array(a) => !a.is_empty(),\n            Value::Object(o) => !o.is_empty(),\n        }\n    }\n\n    /// Get the type name of this value\n    pub fn type_name(&self) -> &'static str {\n        match self {\n            Value::Integer(_) => \"integer\",\n            Value::Float(_) => \"float\",\n            Value::Bool(_) => \"bool\",\n            Value::String(_) => \"string\",\n            Value::Array(_) => \"array\",\n            Value::Object(_) => \"object\",\n            Value::Null => \"null\",\n        }\n    }\n\n    /// Safe length check\n    pub fn len(&self) -> Result<usize> {\n        match self {\n            Value::String(s) => Ok(s.len()),\n            Value::Array(a) => Ok(a.len()),\n            Value::Object(o) => Ok(o.len()),\n            _ => Err(OmniaError::TypeError(format!(\"Cannot get length of {}\", self.type_name()))),\n        }\n    }\n}\n